export type Card = {
  monster: string;
  rank?: number;
};

const SPHINX = "sphinx";

const NO_SPHINX_SCORE = 0;

const SPHINX_BASE_POINTS = 1;

// Variety points: a flat 1 up to and including four types, then 2 per type
// above four (so five types score 2, six types score 4).
const FLAT_VARIETY_POINTS = 1;
const VARIETY_POINTS_PER_TYPE_ABOVE = 2;
const TYPES_BEFORE_VARIETY_SCALES = 4;

const containsSphinx = (army: Card[]): boolean =>
  army.some((card) => card.monster === SPHINX);

// A card's type is its monster; rank marks a variant (e.g. Undead Warrior
// (1) and (3)) and does not make it a separate type.
const typeOf = (card: Card): string => card.monster;

const countDistinctTypes = (army: Card[]): number =>
  new Set(army.map(typeOf)).size;

const varietyPoints = (typeCount: number): number =>
  typeCount > TYPES_BEFORE_VARIETY_SCALES
    ? VARIETY_POINTS_PER_TYPE_ABOVE * (typeCount - TYPES_BEFORE_VARIETY_SCALES)
    : FLAT_VARIETY_POINTS;

export const scoreArmy = (army: Card[]): number => {
  if (!containsSphinx(army)) return NO_SPHINX_SCORE;
  return SPHINX_BASE_POINTS + varietyPoints(countDistinctTypes(army));
};

